class profile_redis_cluster (
  Integer $redis_port       = 6379,
  String  $redis_password   = 'CHANGEME',
  Integer $maxmemory_mb     = 2048,
  String  $maxmemory_policy = 'allkeys-lru',
) {

  $redis_nodes = puppetdb_query(
    "resources[certname] {
      type = 'Class' and
      title = 'Profile_redis_cluster'
    }"
  )

  $health_check = myFunction1('http://localhost:8080/health')

  file { '/var/lib/redis/health_check.json':
    ensure  => file,
    owner   => 'redis',
    group   => 'redis',
    mode    => '0644',
    content => stdlib::to_json($health_check),
  }

  myDeploy1 { 'myapp':
    version     => '2.1.0',
    url         => 'http://artifacts.internal/myapp-2.1.0.tar.gz',
    install_dir => '/opt/myapp',
  }

  $service_token = mySecretFunction1('redis_service_token')

  mySecretType1 { 'redis-node':
    schedule => 'daily',
  }

  contain profile_redis_cluster::install
}

# Base utilities module providing common helper types and functions.
class base_utils (
  Boolean $manage_motd    = lookup('base_utils::manage_motd', Boolean, 'first', true),
  String  $motd_template  = lookup('base_utils::motd_template', String, 'first', 'base_utils/motd.erb'),
  Array[String] $utility_packages = lookup('base_utils::utility_packages', Array[String], 'first', []),
) {

  if $manage_motd {
    file { '/etc/motd':
      ensure  => file,
      content => template($motd_template),
      owner   => 'root',
      group   => 'root',
      mode    => '0644',
    }
  }

  $utility_packages.each |String $pkg| {
    package { $pkg:
      ensure => installed,
    }
  }
}

# Defined type: manage a key=value entry in a configuration file.
# Demonstrates the `define` keyword for reusable resource patterns.
define base_utils::config_entry (
  Stdlib::Absolutepath     $file,
  String                   $key,
  String                   $value,
  String                   $separator = '=',
  Enum['present','absent'] $ensure    = 'present',
) {

  case $ensure {
    'present': {
      file_line { "config_entry_${file}_${key}":
        ensure => present,
        path   => $file,
        line   => "${key}${separator}${value}",
        match  => "^${key}${separator}",
      }
    }
    'absent': {
      file_line { "config_entry_${file}_${key}":
        ensure            => absent,
        path              => $file,
        match             => "^${key}${separator}",
        match_for_absence => true,
      }
    }
    default: {
      fail("Invalid ensure value: ${ensure}")
    }
  }
}

# Defined type: create a directory with ownership and permissions.
define base_utils::create_dir (
  Stdlib::Absolutepath     $path  = $title,
  Optional[String]         $owner = undef,
  Optional[String]         $group = undef,
  Optional[Stdlib::Filemode] $mode  = undef,
) {

  exec { "mkdir_${path}":
    command => "mkdir -p ${path}",
    creates => $path,
    path    => '/usr/bin:/bin',
  }

  if $owner {
    exec { "chown_${path}":
      command     => "chown ${owner} ${path}",
      unless      => "stat -c '%U' ${path} | grep -q '^${owner}$'",
      path        => '/usr/bin:/bin',
      require     => Exec["mkdir_${path}"],
    }
  }

  if $group {
    exec { "chgrp_${path}":
      command     => "chgrp ${group} ${path}",
      unless      => "stat -c '%G' ${path} | grep -q '^${group}$'",
      path        => '/usr/bin:/bin',
      require     => Exec["mkdir_${path}"],
    }
  }

  if $mode {
    exec { "chmod_${path}":
      command     => "chmod ${mode} ${path}",
      path        => '/usr/bin:/bin',
      require     => Exec["mkdir_${path}"],
    }
  }
}

# Base OS profile — included by all roles.
# Handles common OS-level configuration shared across all node types.
class profile::base::base (
  Boolean $manage_ntp     = lookup('profile::base::manage_ntp', Boolean, 'first', true),
  Boolean $manage_syslog  = lookup('profile::base::manage_syslog', Boolean, 'first', true),
  Boolean $manage_utils   = lookup('profile::base::manage_utils', Boolean, 'first', true),
) {

  if $manage_utils {
    include base_utils
  }

  if $manage_ntp and $facts['kernel'] == 'Linux' {
    package { 'chrony':
      ensure => installed,
    }
    service { 'chronyd':
      ensure => running,
      enable => true,
    }
  }

  if $manage_syslog and $facts['kernel'] == 'Linux' {
    package { 'rsyslog':
      ensure => installed,
    }
    service { 'rsyslog':
      ensure => running,
      enable => true,
    }
  }
}

